test "t0" {
    assert (url_encode(str("Hello world!")) == str("Hello%20world%21"));;
}

test "t1" {
    assert (url_encode("a b c") == "a%20b%20c");;
}

test "t2" {
    assert (url_encode("hello world") == "hello%20world");;
}

test "t3" {
    assert (url_encode('Hello World') == 'Hello%20World');;
}

test "t4" {
    assert (url_encode('@') == '%40');;
}

test "t5" {
    assert (url_encode('(') == '%28');
    assert (url_encode('[') == '%5B');
    assert (url_encode('hello world') == 'hello%20world');
    assert (url_encode('HELLO WORLD') == 'HELLO%20WORLD');
    assert (url_encode('*') == '%2A');
    assert (url_encode(str("Hello, World!")) == str("Hello%2C%20World%21"));
    assert (url_encode('"Hello, World!"') == "%22Hello%2C%20World%21%22");
    assert (
        url_encode("this is a tricky input string which might not always work")
        == "this%20is%20a%20tricky%20input%20string%20which%20might%20not%20always%20work"
    );
    assert (url_encode('$') == '%24');
    assert (url_encode('#') == '%23');
    assert (url_encode('%') == '%25');
    assert (url_encode('/') == '%2F');
    assert (url_encode('?') == '%3F');
    assert (url_encode('-') == '%2D');
    assert (url_encode("1 2 3") == "1%202%203");
    assert (url_encode("") == "");
    assert (url_encode("I have spaces") == "I%20have%20spaces");
    assert (url_encode("abc!def") == "abc%21def");
    assert (url_encode('~') == '%7E');
    assert (url_encode("hello") == "hello");
    assert (url_encode('"') == '%22');
    assert (url_encode('>') == '%3E');
    assert (url_encode(' ') == '%20');
    assert (url_encode("abc!def#") == "abc%21def%23");
    assert (url_encode(str("1234567890")) == str("1234567890"));
    assert (url_encode('+') == '%2B');
    assert (url_encode('\'') == '%27');
    assert (url_encode('^') == '%5E');
    assert (url_encode('!') == '%21');
    assert (url_encode("I am a cat!") == "I%20am%20a%20cat%21");
    assert (url_encode("abc") == "abc");
    assert (url_encode("Hello, World!") == "Hello%2C%20World%21");
    assert (url_encode("12345") == "12345");
    assert (url_encode(')') == '%29');;
}

test "t6" {
    assert (url_encode('=') == '%3D');;
}

test "t7" {
    assert (url_encode('<') == '%3C');;
}

test "t8" {
    assert (url_encode('.') == '%2E');;
}

test "t9" {
    assert (url_encode('&') == '%26');;
}
